/* Open-Meteo forecast, cached by the app; null fields stay unavailable. */
(function(root){'use strict';
function value(n){return Number.isFinite(n)?n:null;}
function summary(code){if(!Number.isFinite(code))return 'Conditions indisponibles';if(code===0)return 'Ciel dégagé';if(code<=2)return 'Éclaircies';if(code===3)return 'Nuageux';if(code<=48)return 'Brouillard';if(code<=57)return 'Bruine';if(code<=67)return 'Pluie';if(code<=77)return 'Neige';if(code<=82)return 'Averses';if(code<=86)return 'Averses de neige';return 'Orages';}
function symbol(code){return !Number.isFinite(code)?'cloud':code<3?'sun':code<49?'cloud':code<68?'rain':code<78?'snow':code<83?'rain':code<87?'snow':'storm';}
function normalize(data,city){var current=data&&data.current,hourly=data&&data.hourly,daily=data&&data.daily;if(!current||!Number.isFinite(current.temperature_2m)||!hourly||!Array.isArray(hourly.time))throw Error('Prévisions météo indisponibles.');var index=hourly.time.findIndex(function(t){return t>=current.time;});if(index<0)throw Error('Prévisions horaires indisponibles.');function at(object,key,i){return object&&Array.isArray(object[key])?value(object[key][i]):null;}
 return {city:city.name||city.city,latitude:city.latitude,longitude:city.longitude,temperature:current.temperature_2m,code:value(current.weather_code),summary:summary(current.weather_code),updatedAt:Date.now(),details:true,feels:value(current.apparent_temperature),humidity:value(current.relative_humidity_2m),wind:value(current.wind_speed_10m),rain:value(current.precipitation),hours:hourly.time.slice(index,index+24).map(function(t,n){var i=index+n;return {time:t.slice(11,13)+' h',date:t.slice(0,10),temp:at(hourly,'temperature_2m',i),code:at(hourly,'weather_code',i),rain:at(hourly,'precipitation_probability',i)};}),days:daily&&Array.isArray(daily.time)?daily.time.slice(0,7).map(function(t,i){return {date:t,code:at(daily,'weather_code',i),min:at(daily,'temperature_2m_min',i),max:at(daily,'temperature_2m_max',i),rain:at(daily,'precipitation_sum',i),uv:at(daily,'uv_index_max',i),sunrise:daily.sunrise&&daily.sunrise[i],sunset:daily.sunset&&daily.sunset[i]};}):[]};
}
async function load(city,fetcher,signal){if(!city||!Number.isFinite(city.latitude)||!Number.isFinite(city.longitude))throw Error('Choisis une ville.');var query=new URLSearchParams({latitude:city.latitude,longitude:city.longitude,current:'temperature_2m,weather_code,apparent_temperature,relative_humidity_2m,wind_speed_10m,precipitation',hourly:'temperature_2m,weather_code,precipitation_probability',daily:'weather_code,temperature_2m_max,temperature_2m_min,sunrise,sunset,precipitation_sum,uv_index_max',forecast_days:7,timezone:'Europe/Zurich'});var response=await(fetcher||fetch)('https://api.open-meteo.com/v1/forecast?'+query,{signal:signal,credentials:'omit',referrerPolicy:'no-referrer'});if(!response.ok)throw Error('La météo est indisponible pour le moment.');return normalize(await response.json(),city);}
root.HubWeather={load:load,normalize:normalize,summary:summary,symbol:symbol};
})(typeof window==='undefined'?globalThis:window);
